        "file": "s3_secure.tf",
        "lang": "hcl",
        "kind": "secure",
        "code": "resource \"aws_s3_bucket\" \"invoices\" {\n  bucket = \"acme-invoices-prod\"\n}\n\n# 1. Public ACLs and public policies are refused, whatever anyone writes later\nresource \"aws_s3_bucket_public_access_block\" \"invoices\" {\n  bucket                  = aws_s3_bucket.invoices.id\n  block_public_acls       = true\n  ignore_public_acls      = true\n  block_public_policy     = true\n  restrict_public_buckets = true\n}\n\n# 2. Encryption at rest with a customer-managed KMS key, rotated every year\nresource \"aws_kms_key\" \"invoices\" {\n  description         = \"Encrypts the invoices bucket\"\n  enable_key_rotation = true\n}\n\nresource \"aws_s3_bucket_server_side_encryption_configuration\" \"invoices\" {\n  bucket = aws_s3_bucket.invoices.id\n\n  rule {\n    apply_server_side_encryption_by_default {\n      sse_algorithm     = \"aws:kms\"\n      kms_master_key_id = aws_kms_key.invoices.arn\n    }\n    bucket_key_enabled = true # fewer KMS calls, lower cost\n  }\n}\n\n# 3. Versioning: protection against accidental deletion and ransomware\nresource \"aws_s3_bucket_versioning\" \"invoices\" {\n  bucket = aws_s3_bucket.invoices.id\n\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n\n# 4. Encryption in transit: every request made without TLS is denied\nresource \"aws_s3_bucket_policy\" \"invoices\" {\n  bucket = aws_s3_bucket.invoices.id\n  policy = jsonencode({\n    Version = \"2012-10-17\"\n    Statement = [{\n      Sid       = \"DenyInsecureTransport\"\n      Effect    = \"Deny\"\n      Principal = \"*\"\n      Action    = \"s3:*\"\n      Resource = [\n        aws_s3_bucket.invoices.arn,\n        \"${aws_s3_bucket.invoices.arn}/*\",\n      ]\n      Condition = {\n        Bool = { \"aws:SecureTransport\" = \"false\" }\n      }\n    }]\n  })\n}\n",
