        "code": "#!/usr/bin/env bash\nset -euo pipefail\nBUCKET=acme-hr-documents\nINSTANCE=i-0abc123def4567890\n\n# 1. Block Public Access on the bucket\naws s3api put-public-access-block --bucket \"$BUCKET\" \\\n  --public-access-block-configuration \\\n  BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true\n\n# 2. Versioning\naws s3api put-bucket-versioning --bucket \"$BUCKET\" \\\n  --versioning-configuration Status=Enabled\n\n# 3. Deny every request that does not use TLS\ncat > tls-only.json <<EOF\n{\n  \"Version\": \"2012-10-17\",\n  \"Statement\": [{\n    \"Sid\": \"DenyInsecureTransport\",\n    \"Effect\": \"Deny\",\n    \"Principal\": \"*\",\n    \"Action\": \"s3:*\",\n    \"Resource\": [\"arn:aws:s3:::$BUCKET\", \"arn:aws:s3:::$BUCKET/*\"],\n    \"Condition\": {\"Bool\": {\"aws:SecureTransport\": \"false\"}}\n  }]\n}\nEOF\naws s3api put-bucket-policy --bucket \"$BUCKET\" --policy file://tls-only.json\n\n# 4. IMDSv2 only on the instance\naws ec2 modify-instance-metadata-options --instance-id \"$INSTANCE\" \\\n  --http-tokens required --http-endpoint enabled --http-put-response-hop-limit 1\n\n# 5. Verification\naws s3api get-public-access-block --bucket \"$BUCKET\"\naws ec2 describe-instances --instance-ids \"$INSTANCE\" \\\n  --query 'Reservations[].Instances[].MetadataOptions.HttpTokens' --output text\n",
