        "lang": "hcl",
        "kind": "secure",
        "code": "# The provider must authenticate to storage with Entra ID, since account keys are disabled\nprovider \"azurerm\" {\n  features {}\n  storage_use_azuread = true\n}\n\nresource \"azurerm_resource_group\" \"prod\" {\n  name     = \"rg-prod\"\n  location = \"westeurope\"\n}\n\nresource \"azurerm_network_security_group\" \"web\" {\n  name                = \"nsg-web\"\n  location            = azurerm_resource_group.prod.location\n  resource_group_name = azurerm_resource_group.prod.name\n\n  # The only inbound flow from the Internet: HTTPS.\n  # No 22 / 3389: administration goes through Azure Bastion.\n  security_rule {\n    name                       = \"allow-https-in\"\n    priority                   = 100\n    direction                  = \"Inbound\"\n    access                     = \"Allow\"\n    protocol                   = \"Tcp\"\n    source_port_range          = \"*\"\n    destination_port_range     = \"443\"\n    source_address_prefix      = \"Internet\"\n    destination_address_prefix = \"*\"\n  }\n  # Everything else from the Internet is refused by the default rule DenyAllInBound (65500)\n}\n\nresource \"azurerm_storage_account\" \"docs\" {\n  name                     = \"acmedocsprod\"\n  resource_group_name      = azurerm_resource_group.prod.name\n  location                 = azurerm_resource_group.prod.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n\n  min_tls_version                 = \"TLS1_2\"\n  https_traffic_only_enabled      = true\n  allow_nested_items_to_be_public = false # anonymous access impossible, even by mistake\n  shared_access_key_enabled       = false # Entra ID identities only: every access is attributable\n  public_network_access_enabled   = false # reachable through a private endpoint only\n\n  blob_properties {\n    versioning_enabled = true\n\n    delete_retention_policy {\n      days = 30 # deleted blobs can be restored for 30 days\n    }\n  }\n}\n\nresource \"azurerm_storage_container\" \"contracts\" {\n  name                  = \"contracts\"\n  storage_account_id    = azurerm_storage_account.docs.id\n  container_access_type = \"private\"\n}\n",
