        "code": "variable \"org_id\" {\n  type        = string\n  description = \"Numeric organisation ID, for example 123456789012\"\n}\n\n# Nobody in the organisation can create a service account key any more\nresource \"google_org_policy_policy\" \"no_sa_keys\" {\n  name   = \"organizations/${var.org_id}/policies/iam.disableServiceAccountKeyCreation\"\n  parent = \"organizations/${var.org_id}\"\n\n  spec {\n    rules {\n      enforce = \"TRUE\"\n    }\n  }\n}\n\n# No bucket of the organisation can be opened to allUsers / allAuthenticatedUsers\nresource \"google_org_policy_policy\" \"no_public_buckets\" {\n  name   = \"organizations/${var.org_id}/policies/storage.publicAccessPrevention\"\n  parent = \"organizations/${var.org_id}\"\n\n  spec {\n    rules {\n      enforce = \"TRUE\"\n    }\n  }\n}\n",
